const uint16_t* houseTile(uint8_t x, uint8_t y) {
    if (x >= 20 || y >= 15) return HOUSE_TILES[0];
    uint8_t id = pgm_read_byte(&HOUSE_ART[y][x]);
    if (id >= (sizeof(HOUSE_TILES) / sizeof(HOUSE_TILES[0]))) return HOUSE_TILES[0];
    return HOUSE_TILES[id];
}

uint8_t houseGround(uint8_t x, uint8_t y) {
    if (x >= 20 || y >= 15) return 4;  // G_FENCE
    return pgm_read_byte(&HOUSE_GROUND[y][x]);
}

